	"""
	Write a function to find the number of ways to fill it with 2 x 1 dominoes for the given 3 x n board.
	>>> count_ways(2)
	3
	>>> count_ways(8)
	153
	>>> count_ways(12)
	2131
	"""

def count_ways(n):
    if n == 0:
        return 1
    elif n == 1:
        return 0
    else:
        a, b = 1, 1
        for i in range(2, n + 1):
            a, b = b, (a + 4 * b) % 1000000007
        return b

