def binomial_Coeff(n,k):
    """
    Write a python function to find binomial co-efficient.
    >>> binomial_Coeff(5,2)
    10
    >>> binomial_Coeff(4,3)
    4
    >>> binomial_Coeff(3,2)
    3
    """

def binomial_Coeff(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return binomial_Coeff(n - 1, k - 1) + binomial_Coeff(n - 1, k)

