def find_Sum(arr,n):
    """
    Write a python function to find the sum of repeated elements in a given array.
    >>> find_Sum([1,2,3,1,1,4,5,6],8)
    3
    >>> find_Sum([1,2,3,1,1],5)
    3
    >>> find_Sum([1,1,2],3)
    2
    """

def find_Sum(arr,n):
    repeated_sum = 0
    seen = set()
    count = {}

    for i in range(n):
        if arr[i] in count:
            count[arr[i]] += 1
        else:
            count[arr[i]] = 1

    for num, freq in count.items():
        if freq > 1:
            repeated_sum += (freq * num) - num

    return repeated_sum

