def compute_Last_Digit(A,B):
    """
    Write a python function to find the last digit when factorial of a divides factorial of b.
    >>> compute_Last_Digit(2,4)
    2
    >>> compute_Last_Digit(6,8)
    6
    >>> compute_Last_Digit(1,2)
    2
    """

def compute_Last_Digit(A,B):
    if A == B:
        return 1
    elif A == 0 or A == 1:
        return B % 10
    else:
        count_2 = 0
        count_5 = 0
        for i in range(A+1, B+1):
            while i % 2 == 0:
                count_2 += 1
                i //= 2
            while i % 5 == 0:
                count_5 += 1
                i //= 5
        trailing_zeroes = min(count_2, count_5)
        if trailing_zeroes > 0:
            return 0
        else:
            result = 1
            for i in range(A+1, B+1):
                result = (result * (i % 10)) % 10
            return result

