def freq_count(list1):
  """
  Write a function to get the frequency of the elements in a list.
  >>> freq_count([10,10,10,10,20,20,20,20,40,40,50,50,30])
  ({10: 4, 20: 4, 40: 2, 50: 2, 30: 1})
  >>> freq_count([1,2,3,4,3,2,4,1,3,1,4])
  ({1:3, 2:2,3:3,4:3})
  >>> freq_count([5,6,7,4,9,10,4,5,6,7,9,5])
  ({10:1,5:3,6:2,7:2,4:2,9:2})
  """

def freq_count(list1):
    frequency = {}
    for item in list1:
        if item in frequency:
            frequency[item] += 1
        else:
            frequency[item] = 1
    return frequency

