def extract_missing(test_list, strt_val, stop_val):
  """
  Write a function to extract the ranges that are missing from the given list with the given start range and end range values.
  >>> extract_missing([(6, 9), (15, 34), (48, 70)], 2, 100)
  [(2, 6), (9, 100), (9, 15), (34, 100), (34, 48), (70, 100)]
  >>> extract_missing([(7, 2), (15, 19), (38, 50)], 5, 60)
  [(5, 7), (2, 60), (2, 15), (19, 60), (19, 38), (50, 60)]
  >>> extract_missing([(7, 2), (15, 19), (38, 50)], 1, 52)
  [(1, 7), (2, 52), (2, 15), (19, 52), (19, 38), (50, 52)]
  """

def extract_missing(test_list, strt_val, stop_val):
    res = []
    for tup in test_list:
        a, b = tup
        if a > b:
            x, y = b, a
            if x > strt_val:
                res.append((strt_val, x))
            if y < stop_val:
                res.append((y, stop_val))
            if x > strt_val and y > x:
                res.append((x, y))
                res.append((x, strt_val))
                res.append((stop_val, y))
        else:
            if a > strt_val:
                res.append((strt_val, a))
            if b < stop_val:
                res.append((b, stop_val))
            if a > strt_val and b > a:
                res.append((a, b))
                res.append((a, strt_val))
                res.append((stop_val, b))
    return res

def extract_missing(test_list, strt_val, stop_val):
  """
  Write a function to extract the ranges that are missing from the given list with the given start range and end range values.
  >>> extract_missing([(6, 9), (15, 34), (48, 70)], 2, 100)
  [(2, 6), (9, 100), (9, 15), (34, 100), (34, 48), (70, 100)]
  >>> extract_missing([(7, 2), (15, 19), (38, 50)], 5, 60)
  [(5, 7), (2, 60), (2, 15), (19, 60), (19, 38), (50, 60)]
  >>> extract_missing([(7, 2), (15, 19), (38, 50)], 1, 52)
  [(1, 7), (2, 52), (2, 15), (19, 52), (19, 38), (50, 52)]
  """

def extract_missing(test_list, strt_val, stop_val):
	res = []
	for tup in test_list:
		a, b = tup
		if a > b:
			x = b
			y = a
			if strt_val < x:
				list.append(res, (strt_val, x))
			if stop_val > y:
				list.append(res, (y, stop_val))
			if strt_val < x and y > x:
				list.extend(res, [(x, y), (x, strt_val), (stop_val, y)])
		else:
			if a > strt_val:
				list.append(res, (strt_val, a))
			if stop_val > b:
				list.append(res, (b, stop_val))
			if a > strt_val and a < b:
				list.extend(res, [(a, b), (a, strt_val), (stop_val, b)])
	return res

