    """
    Write a python function to find whether the given number is present in the infinite sequence or not.
    >>> does_Contain_B(1,7,3)
    True
    >>> does_Contain_B(1,-3,5)
    False
    >>> does_Contain_B(3,2,5)
    False
    """

def does_Contain_B(a, b, c):
    if a <= 0 and (b < 0 or c < 0):
        return False
    if b == 0:
        return True
    try:
        x = (b ** 2 - 4 * a * c) / (2 * a)
        y1 = (-b + x) / 2
        y2 = (-b - x) / 2
        return y1.is_integer() or y2.is_integer()
    except ZeroDivisionError:
        return False

