def get_pell(n):
	"""
	Write a function to calculate the nth pell number.
	>>> get_pell(4)
	12
	>>> get_pell(7)
	169
	>>> get_pell(8)
	408
	"""

def get_pell(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
