def longest_common_subsequence(X, Y, m, n):
    """
    Write a function to find the longest common subsequence for the given two sequences.
    >>> longest_common_subsequence("AGGTAB" , "GXTXAYB", 6, 7)
    4
    >>> longest_common_subsequence("ABCDGH" , "AEDFHR", 6, 6)
    3
    >>> longest_common_subsequence("AXYT" , "AYZX", 4, 4)
    2
    """

if m == 0 or n == 0:
        return 0

    if X[m-1] == Y[n-1]:
        return 1 + longest_common_subsequence(X, Y, m-1, n-1)

    else:
        return max(longest_common_subsequence(X, Y, m, n-1), 
                    longest_common_subsequence(X, Y, m-1, n))

