def check_occurences(test_list):
  """
  Write a function to check the occurrences of records which occur similar times in the given tuples.
  >>> check_occurences([(3, 1), (1, 3), (2, 5), (5, 2), (6, 3)] )
  {(1, 3): 2, (2, 5): 2, (3, 6): 1}
  >>> check_occurences([(4, 2), (2, 4), (3, 6), (6, 3), (7, 4)] )
  {(2, 4): 2, (3, 6): 2, (4, 7): 1}
  >>> check_occurences([(13, 2), (11, 23), (12, 25), (25, 12), (16, 23)] )
  {(2, 13): 1, (11, 23): 1, (12, 25): 2, (16, 23): 1}
  """

def check_occurences(test_list):
    from collections import defaultdict
    occurrence_dict = defaultdict(int)

    for tup in test_list:
        sorted_tup = tuple(sorted(tup))
        occurrence_dict[sorted_tup] += 1

    result = {key: value for key, value in occurrence_dict.items() if list(occurrence_dict.values()).count(value) == value}

    return result

