def harmonic_sum(n):
  """
  Write a function to calculate the harmonic sum of n-1.
  >>> harmonic_sum(7)
  2.5928571428571425
  >>> harmonic_sum(4)
  2.083333333333333
  >>> harmonic_sum(19)
  3.547739657143682
  """

def harmonic_sum(n):
    if n < 2:
        return 1
    else:
        return 1 / (n - 1) + harmonic_sum(n - 1)

