def count_first_elements(test_tup):
  """
  Write a function to find the element count that occurs before the record in the given tuple.
  >>> count_first_elements((1, 5, 7, (4, 6), 10) )
  3
  >>> count_first_elements((2, 9, (5, 7), 11) )
  2
  >>> count_first_elements((11, 15, 5, 8, (2, 3), 8) )
  4
  """

def count_first_elements(test_tup):
    for idx, ele in enumerate(test_tup):
        if isinstance(ele, tuple):
            return idx
    return len(test_tup)

