    Write a python function to check whether the count of inversion of two types are same or not.
    >>> solve([1,0,2],3)
    True
    >>> solve([1,2,0],3)
    False
    >>> solve([1,2,1],3)
    True
    """

def solve(a, n):
    even_inversions = 0
    odd_inversions = 0

    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > a[j]:
                inversion = abs(a[i] - a[j])
                if inversion % 2 == 0:
                    even_inversions += 1
                else:
                    odd_inversions += 1

    return even_inversions == odd_inversions

