def max_sum_increasing_subseq(a, n, index, k):
	"""
	Write a function to find the maximum sum of increasing subsequence from prefix till ith index and also including a given kth element which is after i, i.e., k > i .
	>>> max_sum_increasing_subseq([1, 101, 2, 3, 100, 4, 5 ], 7, 4, 6)
	11
	>>> max_sum_increasing_subseq([1, 101, 2, 3, 100, 4, 5 ], 7, 2, 5)
	7
	>>> max_sum_increasing_subseq([11, 15, 19, 21, 26, 28, 31], 7, 2, 4)
	71
	"""

def max_sum_increasing_subseq(a, n, index, k):
    if index >= n:
        return 0
    if k < index:
        return max_sum_increasing_subseq(a, n, index + 1, k)
    incl = a[index] + max_sum_increasing_subseq(a, n, index + 1, n) if (k == n or a[k] > a[index]) else float('-inf')
    excl = max_sum_increasing_subseq(a, n, index + 1, k)
    return max(incl, excl)

