    {'l': 1, 'a': 2, 'n': 1, 'g': 2, 'u': 1, 'e': 1}
    """

def char_frequency(str1):
    dict = {}
    for n in str1:
        keys = dict.keys()
        if n in keys:
            dict[n] += 1
        else:
            dict[n] = 1
    return dict

