    """
    Write a python function to find number of elements with odd factors in a given range.
    >>> count_Odd_Squares(5,100)
    8
    >>> count_Odd_Squares(8,65)
    6
    >>> count_Odd_Squares(2,5)
    1
    """

def count_Odd_Squares(n, m):
	def isPerfectSquare(x):
		s = int(x**0.5)
		return s**2 == x

	def hasOddFactors(x):
		if isPerfectSquare(x):
			s = int(x**0.5)
			return s % 2 != 0
		return True

	return sum((bool(hasOddFactors(i)) for i in range(n, 1 + m)))

