def first_Element(arr,n,k):
    """
    Write a python function to find the first element occurring k times in a given array.
    >>> first_Element([0,1,2,3,4,5],6,1)
    0
    >>> first_Element([1,2,1,3,4],5,2)
    1
    >>> first_Element([2,3,4,3,5,7,1,2,3,5],10,2)
    2
    """

def first_Element(arr,n,k):
    count = {}
    for i in range(n):
        if arr[i] in count:
            count[arr[i]] += 1
        else:
            count[arr[i]] = 1
    for i in range(n):
        if count[arr[i]] == k:
            return arr[i]
    return -1

