def k_smallest_pairs(nums1, nums2, k):
   """
   Write a function to find k number of pairs which consist of one element from the first array and one element from the second array.
   >>> k_smallest_pairs([1,3,7],[2,4,6],2)
   [[1, 2], [1, 4]]
   >>> k_smallest_pairs([1,3,7],[2,4,6],1)
   [[1, 2]]
   >>> k_smallest_pairs([1,3,7],[2,4,6],7)
   [[1, 2], [1, 4], [3, 2], [1, 6], [3, 4], [3, 6], [7, 2]]
   """

def k_smallest_pairs(nums1, nums2, k):
    import heapq
    min_heap = []

    for i in range(min(len(nums1), k)):
        for j in range(min(len(nums2), k)):
            if len(min_heap) < k:
                heapq.heappush(min_heap, (-(nums1[i] + nums2[j]), nums1[i], nums2[j]))
            elif -(nums1[i] + nums2[j]) > min_heap[0][0]:
                heapq.heapreplace(min_heap, (-(nums1[i] + nums2[j]), nums1[i], nums2[j]))

    return [[pair[1], pair[2]] for pair in min_heap]

