def count_bidirectional(test_list):
  """
  Write a function to count bidirectional tuple pairs.
  >>> count_bidirectional([(5, 6), (1, 2), (6, 5), (9, 1), (6, 5), (2, 1)] )
  '3'
  >>> count_bidirectional([(5, 6), (1, 3), (6, 5), (9, 1), (6, 5), (2, 1)] )
  '2'
  >>> count_bidirectional([(5, 6), (1, 2), (6, 5), (9, 2), (6, 5), (2, 1)] )
  '4'
  """

def count_bidirectional(test_list):
    seen = set()
    count = 0
    for a, b in test_list:
        if (b, a) in seen:
            count += 1
        else:
            seen.add((a, b))
    return str(count)

def count_bidirectional(test_list):
  """
  Write a function to count bidirectional tuple pairs.
  >>> count_bidirectional([(5, 6), (1, 2), (6, 5), (9, 1), (6, 5), (2, 1)] )
  '3'
  >>> count_bidirectional([(5, 6), (1, 3), (6, 5), (9, 1), (6, 5), (2, 1)] )
  '2'
  >>> count_bidirectional([(5, 6), (1, 2), (6, 5), (9, 2), (6, 5), (2, 1)] )
  '4'
  """

def count_bidirectional(test_list):
	seen = set()
	count = 0
	for a, b in test_list:
		if (b, a) in seen:
			count += 1
		else:
			set.add(seen, (a, b))
	return str(count)

