	2
	>>> find_peak([2, 3, 4, 5, 6], 5)
	4
	>>> find_peak([8, 9, 11, 12, 14, 15], 6)
	5
	"""

    if n == 0:
        return -1
    if n == 1:
        return 0
    if arr[0] >= arr[1]:
        return 0
    if arr[n-1] >= arr[n-2]:
        return n-1

    for i in range(1, n-1):
        if arr[i] >= arr[i-1] and arr[i] >= arr[i+1]:
            return i

