def is_subset_sum(set, n, sum):
	"""
	Write a function to determine if there is a subset of the given set with sum equal to the given sum.
	>>> is_subset_sum([3, 34, 4, 12, 5, 2], 6, 9)
	True
	>>> is_subset_sum([3, 34, 4, 12, 5, 2], 6, 30)
	False
	>>> is_subset_sum([3, 34, 4, 12, 5, 2], 6, 15)
	True
	"""

def is_subset_sum(set, n, sum):
    # Base Cases
    if sum == 0:
        return True
    if n == 0 and sum != 0:
        return False

    # If last element is greater than sum, ignore it
    if set[n-1] > sum:
        return is_subset_sum(set, n-1, sum)

    # Else, check if sum can be obtained by any of the following
    # (a) including the last element
    # (b) excluding the last element
    return is_subset_sum(set, n-1, sum) or is_subset_sum(set, n-1, sum-set[n-1])

