def count_element_freq(test_tuple):
  """
  Write a function to count the element frequency in the mixed nested tuple.
  >>> count_element_freq((5, 6, (5, 6), 7, (8, 9), 9) )
  {5: 2, 6: 2, 7: 1, 8: 1, 9: 2}
  >>> count_element_freq((6, 7, (6, 7), 8, (9, 10), 10) )
  {6: 2, 7: 2, 8: 1, 9: 1, 10: 2}
  >>> count_element_freq((7, 8, (7, 8), 9, (10, 11), 11) )
  {7: 2, 8: 2, 9: 1, 10: 1, 11: 2}
  """

from collections import defaultdict

def count_element_freq(test_tuple):
    freq_dict = defaultdict(int)

    def flatten(tup):
        for item in tup:
            if isinstance(item, tuple):
                yield from flatten(item)
            else:
                yield item

    for element in flatten(test_tuple):
        freq_dict[element] += 1

    return dict(freq_dict)

