def lbs(arr):
	"""
	Write a function to find the longest bitonic subsequence for the given array.
	>>> lbs([0 , 8 , 4, 12, 2, 10 , 6 , 14 , 1 , 9 , 5 , 13, 3, 11 , 7 , 15])
	7
	>>> lbs([1, 11, 2, 10, 4, 5, 2, 1])
	6
	>>> lbs([80, 60, 30, 40, 20, 10])
	5
	"""

def lbs(arr):
	n = len(arr)
	lis = []
	for _ in range(n):
		list.append(lis, 1)
	lds = []
	for _ in range(n):
		list.append(lds, 1)

	for i in range(1, n):
		for j in range(0, i):
			if arr[j] < arr[i]:
				lis[i] = max(lis[i], 1 + lis[j])

	for i in reversed(range(n - 1)):
		for j in reversed(range(i + 1, n)):
			if arr[j] < arr[i]:
				lds[i] = max(lds[i], 1 + lds[j])

	maximum = lds[0] + lis[0] - 1
	for i in range(1, n):
		maximum = max((lds[i] + lis[i] - 1), maximum)

	return maximum

