def max_sum_increasing_subsequence(arr, n):
	"""
	Write a function to find the sum of maximum increasing subsequence of the given array.
	>>> max_sum_increasing_subsequence([1, 101, 2, 3, 100, 4, 5], 7)
	106
	>>> max_sum_increasing_subsequence([3, 4, 5, 10], 4)
	22
	>>> max_sum_increasing_subsequence([10, 5, 4, 3], 4)
	10
	"""

def max_sum_increasing_subsequence(arr, n):
    if n == 0:
        return 0

    msis = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and msis[i] < msis[j] + arr[i]:
                msis[i] = msis[j] + arr[i]

    return max(msis)

