def capitalize_first_last_letters(str1):
     """
     Write a python function to capitalize first and last letters of each word of a given string.
     >>> capitalize_first_last_letters("python")
     "PythoN"
     >>> capitalize_first_last_letters("bigdata")
     "BigdatA"
     >>> capitalize_first_last_letters("Hadoop")
     "HadooP"
     """

def capitalize_first_last_letters(str1):
    result = []
    for word in str1.split():
        if len(word) > 1:
            word = word[0].upper() + word[1:-1] + word[-1].upper()
        else:
            word = word.upper()
        result.append(word)
    return ' '.join(result)

