def jacobsthal_lucas(n):
	"""
	Write a function to find the nth jacobsthal-lucas number.
	>>> jacobsthal_lucas(5)
	31
	>>> jacobsthal_lucas(2)
	5
	>>> jacobsthal_lucas(4)
	17
	"""

def jacobsthal_lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        a, b = 2, 1
        for _ in range(2, n + 1):
            a, b = a + 2 * b, a + b
        return b

