def min_coins(coins, m, V):
    """
    Write a function to find minimum number of coins that make a given value.
    >>> min_coins([9, 6, 5, 1] ,4,11)
    2
    >>> min_coins([4,5,6,7,8,9],6,9)
    1
    >>> min_coins([1, 2, 3],3,4)
    2
    """

def min_coins(coins, m, V):
    table = [float('Inf')] * (V + 1)
    table[0] = 0

    for i in range(1, V + 1):
        for j in range(m):
            if coins[j] <= i:
                sub_res = table[i - coins[j]]
                if sub_res != float('Inf') and sub_res + 1 < table[i]:
                    table[i] = sub_res + 1

    return table[V] if table[V] != float('Inf') else -1

