def longest_increasing_subsequence(arr):
	"""
	Write a function to find the length of the longest increasing subsequence of the given sequence.
	>>> longest_increasing_subsequence([10, 22, 9, 33, 21, 50, 41, 60])
	5
	>>> longest_increasing_subsequence([3, 10, 2, 1, 20])
	3
	>>> longest_increasing_subsequence([50, 3, 10, 7, 40, 80])
	4
	"""

def longest_increasing_subsequence(arr):
    if not arr:
        return 0

    n = len(arr)
    lis = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

