def difference(n) :
    """
    Write a python function to find the difference between sum of cubes of first n natural numbers and the sum of first n natural numbers.
    >>> difference(3)
    30
    >>> difference(5)
    210
    >>> difference(2)
    6
    """

def difference(n):
    def sum_of_squares(x):
        return sum(i**3 for i in range(1, x + 1))

    def sum_of_numbers(x):
        return sum(i for i in range(1, x + 1))

    return sum_of_squares(n) - sum_of_numbers(n)

