def assign_elements(test_list):
  """
  Write a function to assign with each element, its pair elements from other similar pairs in the given tuple.
  >>> assign_elements([(5, 3), (7, 5), (2, 7), (3, 8), (8, 4)] )
  {3: [8], 5: [3], 7: [5], 2: [7], 8: [4], 4: []}
  >>> assign_elements([(6, 4), (9, 4), (3, 8), (4, 9), (9, 5)] )
  {4: [9], 6: [4], 9: [4, 5], 8: [], 3: [8], 5: []}
  >>> assign_elements([(6, 2), (6, 8), (4, 9), (4, 9), (3, 7)] )
  {2: [], 6: [2, 8], 8: [], 9: [], 4: [9, 9], 7: [], 3: [7]}
  """

def assign_elements(test_list):
    result = {}
    for a, b in test_list:
        if a not in result:
            result[a] = []
        if b not in result:
            result[b] = []
        if a in [x[1] for x in test_list]:
            result[b].append(a)
        if b in [x[0] for x in test_list]:
            result[a].append(b)
    return result

