def remove_similar_row(test_list):
  """
  Write a function to remove similar rows from the given tuple matrix.
  >>> remove_similar_row([[(4, 5), (3, 2)], [(2, 2), (4, 6)], [(3, 2), (4, 5)]] )
  {((4, 6), (2, 2)), ((4, 5), (3, 2))}
  >>> remove_similar_row([[(5, 6), (4, 3)], [(3, 3), (5, 7)], [(4, 3), (5, 6)]] )
  {((5, 6), (4, 3)), ((5, 7), (3, 3))}
  >>> remove_similar_row([[(6, 7), (5, 4)], [(4, 4), (6, 8)], [(5, 4), (6, 7)]] )
  {((5, 4), (6, 7)), ((4, 4), (6, 8))}
  """

def remove_similar_row(test_list):
    result = set()
    for row in test_list:
        sorted_row = tuple(sorted(row))
        result.add(sorted_row)
    return result

