def first_Digit(n) :
    """
    Write a python function to find the first digit in factorial of a given number.
    >>> first_Digit(5)
    1
    >>> first_Digit(10)
    3
    >>> first_Digit(7)
    5
    """

def first_Digit(n) :
    fact = 1
    for i in range(2, n + 1) :
        fact *= i

    while (fact % 10 == 0) :
        fact //= 10

    while (fact >= 10) :
        fact //= 10

    return int(fact)

