def max_sum_of_three_consecutive(arr, n):
	"""
	Write a function to find the maximum sum that can be formed which has no three consecutive elements present.
	>>> max_sum_of_three_consecutive([100, 1000, 100, 1000, 1], 5)
	2101
	>>> max_sum_of_three_consecutive([3000, 2000, 1000, 3, 10], 5)
	5013
	>>> max_sum_of_three_consecutive([1, 2, 3, 4, 5, 6, 7, 8], 8)
	27
	"""

if n == 0:
    return 0
elif n == 1:
    return arr[0]
elif n == 2:
    return max(arr[0], arr[1])
else:
    incl = max(arr[0], arr[1] + arr[2])
    excl = arr[0]
    for i in range(3, n):
        new_excl = max(excl, incl)
        incl = excl + arr[i]
        excl = new_excl
    return max(excl, incl)

