def sum_Of_Primes(n):
    """
    Write a python function to find sum of prime numbers between 1 to n.
    >>> sum_Of_Primes(10)
    17
    >>> sum_Of_Primes(20)
    77
    >>> sum_Of_Primes(5)
    10
    """

def sum_Of_Primes(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    total = 0
    for i in range(2, n + 1):
        if is_prime(i):
            total += i
    return total

