def min_Swaps(str1,str2) :
    """
    Write a python function to find the minimum number of swaps required to convert one binary string to another.
    >>> min_Swaps("1101","1110")
    1
    >>> min_Swaps("1111","0100")
    "Not Possible"
    >>> min_Swaps("1110000","0001101")
    3
    """

def min_Swaps(str1,str2) :
    if len(str1) != len(str2):
        return "Not Possible"

    swaps = 0
    diff_positions = []

    for i in range(len(str1)):
        if str1[i] != str2[i]:
            diff_positions.append(i)

    if len(diff_positions) % 2 != 0:
        return "Not Possible"

    for i in range(0, len(diff_positions), 2):
        swaps += 1

    return swaps

