def lcs_of_three(X, Y, Z, m, n, o):
	"""
	Write a function to find the longest common subsequence for the given three string sequence.
	>>> lcs_of_three('AGGT12', '12TXAYB', '12XBA', 6, 7, 5)
	2
	>>> lcs_of_three('Reels', 'Reelsfor', 'ReelsforReels', 5, 8, 13)
	5
	>>> lcs_of_three('abcd1e2', 'bc12ea', 'bd1ea', 7, 6, 5)
	3
	"""

def lcs_of_three(X, Y, Z, m, n, o):
    if m == 0 or n == 0 or o == 0:
        return 0
    if X[m-1] == Y[n-1] and X[m-1] == Z[o-1]:
        return 1 + lcs_of_three(X, Y, Z, m-1, n-1, o-1)
    else:
        return max(max(lcs_of_three(X, Y, Z, m, n-1, o), lcs_of_three(X, Y, Z, m-1, n, o)), lcs_of_three(X, Y, Z, m, n, o-1))

