    """
    Write a function to pack consecutive duplicates of a given list elements into sublists.
    >>> pack_consecutive_duplicates([0, 0, 1, 2, 3, 4, 4, 5, 6, 6, 6, 7, 8, 9, 4, 4])
    [[0, 0], [1], [2], [3], [4, 4], [5], [6, 6, 6], [7], [8], [9], [4, 4]]
    >>> pack_consecutive_duplicates([10, 10, 15, 19, 18, 18, 17, 26, 26, 17, 18, 10])
    [[10, 10], [15], [19], [18, 18], [17], [26, 26], [17], [18], [10]]
    >>> pack_consecutive_duplicates(['a', 'a', 'b', 'c', 'd', 'd'])
    [['a', 'a'], ['b'], ['c'], ['d', 'd']]
    """

def pack_consecutive_duplicates(list1):
    if not list1:
        return []

    packed = [[list1[0]]]
    for element in list1[1:]:
        if element == packed[-1][0]:
            packed[-1].append(element)
        else:
            packed.append([element])
    return packed

