    >>> merge_dictionaries({ "G": "Green", "W": "White" },{ "O": "Orange", "W": "White", "B": "Black" })
    {'W': 'White', 'O': 'Orange', 'G': 'Green', 'B': 'Black'}
    """

def merge_dictionaries(dict1, dict2):
    return {**dict1, **dict2}

