def get_Number(n, k):
    """
    Write a python function to find the kth element in an array containing odd elements first and then even elements.
    >>> get_Number(8,5)
    2
    >>> get_Number(7,2)
    3
    >>> get_Number(5,2)
    3
    """

def get_Number(n, k):
    odd_elements = (n + 1) // 2
    if k <= odd_elements:
        return 2 * k - 1
    else:
        return 2 * (k - odd_elements)

