def Sum(N):
    """
    Write a python function to find sum of all prime divisors of a given number.
    >>> Sum(60)
    10
    >>> Sum(39)
    16
    >>> Sum(40)
    7
    """

def Sum(N):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    prime_sum = 0
    for i in range(2, N + 1):
        if N % i == 0 and is_prime(i):
            prime_sum += i
    return prime_sum

