def min_Num(arr,n):
    """
    Write a python function to add a minimum number such that the sum of array becomes even.
    >>> min_Num([1,2,3,4,5,6,7,8,9],9)
    1
    >>> min_Num([1,2,3,4,5,6,7,8],8)
    2
    >>> min_Num([1,2,3],3)
    2
    """

def min_Num(arr, n):
    total_sum = sum(arr)
    if total_sum % 2 == 0:
        return 0
    else:
        for num in arr:
            if (total_sum - num) % 2 == 0:
                return 1
        return 2

