def lobb_num(n, m):
	"""
	Write a function to find ln, m lobb number.
	>>> lobb_num(5, 3)
	35
	>>> lobb_num(3, 2)
	5
	>>> lobb_num(4, 2)
	20
	"""

def lobb_num(n, m):
    if n == 0 and m == 0:
        return 1
    if n < 0 or m < 0 or m > n:
        return 0
    return ((n + m) * lobb_num(n - 1, m - 1) + (n - m) * lobb_num(n - 1, m + 1)) // (n + 1)

