def find_triplet_array(A, arr_size, sum):
	"""
	Write a function to find if there is a triplet in the array whose sum is equal to a given value.
	>>> find_triplet_array([1, 4, 45, 6, 10, 8], 6, 22)
	(4, 10, 8)
	>>> find_triplet_array([12, 3, 5, 2, 6, 9], 6, 24)
	(12, 3, 9)
	>>> find_triplet_array([1, 2, 3, 4, 5], 5, 9)
	(1, 3, 5)
	"""

def find_triplet_array(A, arr_size, sum):
    for i in range(0, arr_size - 2):
        for j in range(i + 1, arr_size - 1):
            for k in range(j + 1, arr_size):
                if A[i] + A[j] + A[k] == sum:
                    return (A[i], A[j], A[k])
    return None

