def count_elim(num):
  """
  Write a function to count the elements in a list until an element is a tuple.
  >>> count_elim([10,20,30,(10,20),40])
  3
  >>> count_elim([10,(20,30),(10,20),40])
  1
  >>> count_elim([(10,(20,30,(10,20),40))])
  0
  """

def count_elim(num):
    for i, element in enumerate(num):
        if isinstance(element, tuple):
            return i
    return len(num)

