def get_noOfways(n):
    """
    Write a function to solve tiling problem.
    >>> get_noOfways(4)
    3
    >>> get_noOfways(3)
    2
    >>> get_noOfways(5)
    5
    """

def get_noOfways(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        a, b = 1, 1
        for i in range(3, n + 1):
            a, b = b, a + b
        return b

