def floor_Max(A,B,N):
    """
    Write a python function to find maximum possible value for the given periodic function.
    >>> floor_Max(11,10,9)
    9
    >>> floor_Max(5,7,4)
    2
    >>> floor_Max(2,2,1)
    1
    """

def floor_Max(A,B,N):
    if A >= B:
        return N - (N // A) * A
    else:
        return B * (N // A)

