def maximum_segments(n, a, b, c) :
	"""
	Write a function to find the maximum number of segments of lengths a, b and c that can be formed from n.
	>>> maximum_segments(7, 5, 2, 5)
	2
	>>> maximum_segments(17, 2, 1, 3)
	17
	>>> maximum_segments(18, 16, 3, 6)
	6
	"""

def maximum_segments(n, a, b, c):
	dp = []
	for _ in range((1 + n)):
		list.append(dp, 0)

	for i in range(1, 1 + n):
		if i >= a:
			dp[i] = max(dp[i], 1 + dp[i - a])
		if i >= b:
			dp[i] = max(dp[i], dp[i - b] + 1)
		if i >= c:
			dp[i] = max(dp[i], dp[i - c] + 1)

	return dp[n]

